import {NextRequest,NextResponse} from 'next/server';import {z} from 'zod';import {db} from '@/lib/db';import {requireRole,currentVendor} from '@/lib/auth';import {slugify} from '@/lib/http';
const schema=z.object({name:z.string().min(2),categoryId:z.string(),description:z.string().min(5),price:z.coerce.number().positive(),stock:z.coerce.number().int().min(0),brand:z.string().optional(),sku:z.string().optional(),imageUrl:z.url().optional().or(z.literal('')),isWholesale:z.boolean().optional(),minOrderQuantity:z.coerce.number().int().min(1).default(1)});
export async function GET(){try{const u=await requireRole('VENDOR');const v=await currentVendor(u.id);if(!v)return NextResponse.json({error:'Vendor profile not found.'},{status:404});const products=await db.product.findMany({where:{vendorId:v.id},include:{category:true},orderBy:{createdAt:'desc'}});return NextResponse.json({products});}catch(e){return NextResponse.json({error:e instanceof Error?e.message:'Failed'},{status:401});}}
export async function POST(req:NextRequest){try{const u=await requireRole('VENDOR');const v=await currentVendor(u.id);if(!v)return NextResponse.json({error:'Vendor profile not found.'},{status:404});const x=schema.parse(await req.json());const category=await db.category.findUnique({where:{id:x.categoryId}});if(!category)return NextResponse.json({error:'Select a valid category.'},{status:400});const slug=`${slugify(x.name)}-${Math.random().toString(36).slice(2,7)}`;const product=await db.product.create({data:{...x,brand:x.brand||null,sku:x.sku||null,imageUrl:x.imageUrl||null,slug,vendorId:v.id,categoryId:category.id,status:'PENDING'}});return NextResponse.json({product,message:'Listing submitted for admin review.'},{status:201});}catch(e){return NextResponse.json({error:e instanceof Error?e.message:'Could not submit listing.'},{status:400});}}
